CREATE OR REPLACE FUNCTION public.finance_invoice_receipt_action_v2(p_invoice_ids text[], p_action text, p_idempotency_key text, p_expected_versions jsonb, p_note text DEFAULT ''::text, p_files jsonb DEFAULT '[]'::jsonb, p_data_environment text DEFAULT 'production'::text, p_amounts jsonb DEFAULT NULL::jsonb, p_received_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '5s'
AS $function$
declare a public.finance_users%rowtype;i public.invoices%rowtype;r private.finance_ar_receipts_v1%rowtype;v_id text;v_digest text;v_cached jsonb;v_saved text;
 v_result jsonb;v_rows jsonb:='[]';v_steps jsonb;v_files jsonb;v_now timestamptz:=clock_timestamp();v_today date:=(clock_timestamp() at time zone 'Asia/Taipei')::date;
 v_date date;v_ar jsonb;v_amount numeric;v_collectible numeric;v_received numeric;v_amount_map jsonb:='{}';v_date_map jsonb:='{}';v_event uuid;v_final_balance numeric;
 v_prev_key text:=coalesce(current_setting('app.finance_receipt_operation',true),'');v_prev_actor text:=coalesce(current_setting('app.finance_receipt_actor',true),'');
begin
 a:=private.finance_correction_actor_v1();
 if p_action is null or p_action not in ('submit','approve','return') or p_data_environment is null or p_data_environment not in ('production','test')
  or p_invoice_ids is null or cardinality(p_invoice_ids) not between 1 and 150
  or cardinality(p_invoice_ids)<>(select count(distinct x) from unnest(p_invoice_ids) x)
  or coalesce(p_idempotency_key,'') !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$'
  or length(coalesce(p_note,''))>2000 or (p_action='return' and length(btrim(coalesce(p_note,'')))<3)
  or jsonb_typeof(p_expected_versions) is distinct from 'object' then raise exception '收款操作、原因、版本或識別碼格式不正確' using errcode='22023';end if;
 if (select count(*) from jsonb_object_keys(p_expected_versions))<>cardinality(p_invoice_ids)
  or exists(select 1 from unnest(p_invoice_ids) id where coalesce(p_expected_versions->>id,'') !~ '^[1-9][0-9]{0,18}$') then raise exception '收款資料版本不完整，請重新開啟核對' using errcode='40001';end if;
 if p_action<>'submit' and (p_amounts is not null or p_received_date is not null) then raise exception '覆核不得更改已送出的收款金額或日期，請退回後重新提交' using errcode='22023';end if;
 if p_amounts is not null and (jsonb_typeof(p_amounts) is distinct from 'object') then raise exception '本次收款金額格式不正確' using errcode='22023';end if;
 if p_amounts is not null and ((select count(*) from jsonb_object_keys(p_amounts))<>cardinality(p_invoice_ids)
  or exists(select 1 from unnest(p_invoice_ids) id where coalesce(p_amounts->>id,'') !~ '^[0-9]{1,16}(\.[0-9]{1,2})?$' or jsonb_typeof(p_amounts->id) is distinct from 'number')) then raise exception '請逐張指定最多兩位小數的本次實收金額' using errcode='22023';end if;
 if not private.finance_correction_role_v1(a.tenant_id,a.id,null,array[case when p_action='submit' then 'accountant' else 'ceo' end]) then raise exception '收款證明只能由正式會計提交，收款確認與退回只能由有效執行長執行' using errcode='42501';end if;
 -- Preserve the exact v1 digest for old callers and completed operations.
 v_result:=jsonb_build_object('ids',p_invoice_ids,'action',p_action,'versions',p_expected_versions,'note',coalesce(p_note,''),'files',p_files);
 if p_amounts is not null or p_received_date is not null then v_result:=v_result||jsonb_build_object('amounts',p_amounts,'receivedDate',p_received_date);end if;
 v_digest:=encode(sha256(v_result::text::bytea),'hex');
 insert into private.finance_receipt_operations_v1(tenant_id,data_environment,actor_id,operation_key,digest,invoice_ids)
 values(a.tenant_id,p_data_environment,a.id,p_idempotency_key,v_digest,p_invoice_ids) on conflict do nothing;
 select digest,response into v_saved,v_cached from private.finance_receipt_operations_v1 where tenant_id=a.tenant_id and data_environment=p_data_environment and actor_id=a.id and operation_key=p_idempotency_key for update;
 if v_saved is distinct from v_digest then raise exception '相同操作識別碼不可使用不同收款內容' using errcode='23505';end if;
 if v_cached is not null then return v_cached||jsonb_build_object('idempotent_replay',true);end if;
 update private.finance_receipt_operations_v1 set writing_transaction=pg_current_xact_id()::text where tenant_id=a.tenant_id and data_environment=p_data_environment and actor_id=a.id and operation_key=p_idempotency_key;
 perform set_config('app.finance_receipt_operation',p_idempotency_key,true);perform set_config('app.finance_receipt_actor',a.id,true);
 for v_id in select id from unnest(p_invoice_ids) id order by id loop
  select * into i from public.invoices where tenant_id=a.tenant_id and data_environment=p_data_environment and id=v_id for update;
  if not found or public.can_read_invoice(i) is distinct from true then raise exception '無權讀取此租戶／環境的發票' using errcode='42501';end if;
  if i.row_version is distinct from (p_expected_versions->>v_id)::bigint then raise exception '收款內容已更新，請重新開啟核對' using errcode='40001';end if;
  if i.voided_at is not null or i.approval_status in ('rejected','cancelled','voided') or i.status in ('paid','void','voided','cancelled','rejected')
   or not private.finance_receipt_route_ready_v1(i.steps)
   or (p_action='submit' and i.status not in ('unpaid','partial'))
   or (p_action<>'submit' and i.status is distinct from 'pending_receipt_review') then raise exception '發票不在此收款關卡，整批未更新' using errcode='55000';end if;
  v_files:=case when jsonb_typeof(p_files)='object' then p_files->i.id else p_files end;
  if p_action='submit' and not private.finance_receipt_files_valid_v1(i,v_files,a.id) then raise exception '收款證明須為本人上傳、屬於此單或批次且原檔存在的正式附件' using errcode='42501';end if;
  if p_action='approve' and (i.receipt_submitted_at is null or not private.finance_receipt_files_valid_v1(i,i.receipt_files)) then raise exception '未有完整正式收款證明，不能確認入帳' using errcode='23514';end if;
  select * into r from private.finance_ar_receipts_v1 where tenant_id=a.tenant_id and data_environment=p_data_environment and invoice_id=i.id and status='pending' for update;
  v_ar:=private.finance_ar_invoice_v1(i,v_today);
  v_received:=(v_ar->>'receivedAmount')::numeric;
  v_collectible:=case when (v_ar->>'recognizedAmount')::numeric>0 then (v_ar->>'outstandingAmount')::numeric else coalesce(i.total,i.amount,0)-(v_ar->>'arAllowanceAmount')::numeric-v_received end;
  if p_action='submit' then
   if r.id is not null then raise exception '此發票已有待確認收款' using errcode='55000';end if;
   if (i.status='partial' or i.cash_receipt_posted_at is not null) and v_received<=0 then raise exception '舊收款狀態缺少可核對分錄，請先核對原帳，不可推算實收' using errcode='23514';end if;
   v_amount:=coalesce((p_amounts->>i.id)::numeric,v_collectible);v_date:=coalesce(p_received_date,v_today);
  else v_amount:=coalesce(r.amount,coalesce(i.total,i.amount,0));v_date:=coalesce(r.received_date,v_today);
  end if;
  if p_action<>'return' then
   if v_amount<=0 or v_amount<>round(v_amount,2) or v_amount>v_collectible then raise exception '本次實收金額必須大於零且不可超過正式剩餘應收' using errcode='23514';end if;
   if p_action='approve' and r.id is null and v_amount<>v_collectible then raise exception '舊覆核金額與現行餘額不同，請退回重新核對' using errcode='23514';end if;
   if v_date>v_today or (i.invoice_date is not null and v_date<i.invoice_date) then raise exception '收款日期不可晚於今天或早於發票日期' using errcode='22023';end if;
  end if;
  if p_action='approve' then perform private.finance_assert_period_open(a.tenant_id,p_data_environment,i.entity_id,v_date,'發票收款入帳');end if;
  v_amount_map:=v_amount_map||jsonb_build_object(i.id,v_amount);v_date_map:=v_date_map||jsonb_build_object(i.id,v_date);
 end loop;
 for v_id in select id from unnest(p_invoice_ids) id order by id loop
  select * into i from public.invoices where tenant_id=a.tenant_id and data_environment=p_data_environment and id=v_id;
  select * into r from private.finance_ar_receipts_v1 where tenant_id=a.tenant_id and data_environment=p_data_environment and invoice_id=i.id and status='pending';
  v_amount:=(v_amount_map->>i.id)::numeric;v_date:=(v_date_map->>i.id)::date;
  if p_action='submit' then
   v_files:=case when jsonb_typeof(p_files)='object' then p_files->i.id else p_files end;
   insert into private.finance_ar_receipts_v1(tenant_id,data_environment,invoice_id,amount,received_date,status,files,submit_key,submitted_by,note)
    values(a.tenant_id,p_data_environment,i.id,v_amount,v_date,'pending',v_files,p_idempotency_key,a.id,coalesce(p_note,'')) returning id into v_event;
   update public.invoices set status='pending_receipt_review',receipt_files=v_files,receipt_submitted_at=v_now,receipt_submitted_by=a.name,receipt_note=coalesce(p_note,''),updated_at=v_now where id=i.id;
  elsif p_action='return' then
   v_ar:=private.finance_ar_invoice_v1(i,v_today);
   update private.finance_ar_receipts_v1 set status='returned',reviewed_by=a.id,reviewed_at=v_now,review_key=p_idempotency_key where id=r.id;
   update public.invoices set status=case when (v_ar->>'receivedAmount')::numeric>0 then 'partial' else 'unpaid' end,receipt_reviewed_at=v_now,receipt_reviewed_by=a.name,receipt_review_note=p_note,updated_at=v_now where id=i.id;
   v_event:=r.id;
  else
   if r.id is null then
    insert into private.finance_ar_receipts_v1(tenant_id,data_environment,invoice_id,amount,received_date,status,files,submit_key,submitted_by,note)
    values(a.tenant_id,p_data_environment,i.id,v_amount,v_date,'pending',i.receipt_files,'legacy-review:'||p_idempotency_key,a.id,'舊版完整證明覆核') returning * into r;
   end if;
   v_event:=r.id;
   select jsonb_agg(case when s->>'rk'='applicant_invoice_delivery' and coalesce(s->>'a','')='' then
    private.finance_income_append_step_action(s,a.id,a.name,'執行長確認收款後完成交付','已檢查正式收款證明','[]')||jsonb_build_object('a','approved','autoSkip',true,'autoSkipReason','receipt_confirmed_by_ceo') else s end order by ord) into v_steps
    from jsonb_array_elements(i.steps) with ordinality t(s,ord);
   -- Preserve the existing revenue writer's final-approval contract. This
   -- intermediate state is inside the same transaction and never observable.
   update public.invoices set status='paid',steps=v_steps,approval_status='completed',approval_step=jsonb_array_length(v_steps),updated_at=v_now where id=i.id;
   v_result:=private.finance_receipt_revenue_ready_v1(i.id);
   if v_result->>'ok' is distinct from 'true' or coalesce((v_result->>'deferred')::boolean,false) then raise exception '收入認列尚未完成，收款整批未入帳' using errcode='23514';end if;
   select * into i from public.invoices where id=v_id;
   v_ar:=private.finance_ar_invoice_v1(i,v_today);v_collectible:=(v_ar->>'outstandingAmount')::numeric;
   if v_amount>v_collectible then raise exception '收入認列後的正式應收不足，收款整批未入帳' using errcode='23514';end if;
   insert into public.ledger_entries(entry_date,description,entity_id,department_code,debit,credit,account_code,account_name,reference_no,posting_key,source_type,source_id,source_no,tenant_id,data_environment)
   values(v_date,'發票分次收款 — '||coalesce(i.buyer,''),i.entity_id,i.department_code,v_amount,0,'1112','銀行存款',i.no,'tenant:'||a.tenant_id::text||':env:'||p_data_environment||':invoice:'||i.id||':receipt:'||v_event::text||':bank','invoice',i.id,i.no,a.tenant_id,p_data_environment),
    (v_date,'沖轉應收帳款 — '||coalesce(i.buyer,''),i.entity_id,i.department_code,0,v_amount,'1123','應收帳款',i.no,'tenant:'||a.tenant_id::text||':env:'||p_data_environment||':invoice:'||i.id||':receipt:'||v_event::text||':ar','invoice',i.id,i.no,a.tenant_id,p_data_environment);
   v_final_balance:=v_collectible-v_amount;
   update private.finance_ar_receipts_v1 set status='approved',reviewed_by=a.id,reviewed_at=v_now,review_key=p_idempotency_key where id=v_event;
   update public.invoices set status=case when v_final_balance=0 then 'paid' else 'partial' end,
    paid_at=case when v_final_balance=0 then (v_date::timestamp at time zone 'Asia/Taipei') else null end,
    cash_receipt_posted_at=coalesce(cash_receipt_posted_at,v_now),receipt_reviewed_at=v_now,receipt_reviewed_by=a.name,receipt_review_note=coalesce(p_note,''),updated_at=v_now where id=i.id;
  end if;
  insert into public.module_audit_logs(table_name,row_id,action,actor_email,before_data,after_data)
   values('invoice_receipt',i.id,upper(p_action),a.email,jsonb_build_object('status',i.status,'row_version',i.row_version,'receipt_files',i.receipt_files),jsonb_build_object('actorId',a.id,'note',p_note,'at',v_now,'operationKey',p_idempotency_key,'receiptId',v_event,'amount',v_amount,'receivedDate',v_date));
  insert into private.finance_ar_audit_v1(tenant_id,data_environment,invoice_id,actor_id,action,operation_key,before_data,after_data)
   values(a.tenant_id,p_data_environment,i.id,a.id,'receipt_'||p_action,p_idempotency_key,jsonb_build_object('rowVersion',p_expected_versions->i.id),jsonb_build_object('receiptId',v_event,'amount',v_amount,'receivedDate',v_date));
  v_rows:=v_rows||jsonb_build_array(jsonb_build_object('id',i.id,'action',p_action,'receiptId',v_event,'amount',v_amount,'receivedDate',v_date));
 end loop;
 v_result:=jsonb_build_object('ok',true,'count',cardinality(p_invoice_ids),'rows',v_rows,'idempotent_replay',false);
 update private.finance_receipt_operations_v1 set response=v_result,writing_transaction=null where tenant_id=a.tenant_id and data_environment=p_data_environment and actor_id=a.id and operation_key=p_idempotency_key;
 perform set_config('app.finance_receipt_operation',v_prev_key,true);perform set_config('app.finance_receipt_actor',v_prev_actor,true);
 return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_income_resubmit_revision_rows_v2(p_document_type text, p_tenant_id uuid, p_actor_finance_user_id text, p_actor_name text, p_data_environment text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_item jsonb;
  v_expected_row_version bigint;
  v_item_key text;
  v_id text;
  v_comment text;
  v_files jsonb;
  v_patch jsonb;
  v_invoice public.invoices%rowtype;
  v_bill public.bills%rowtype;
  v_steps jsonb;
  v_active_index int;
  v_step jsonb;
  v_step_updated jsonb;
  v_status jsonb;
  v_amount numeric;
  v_tax numeric;
  v_total numeric;
  v_identifier_type text;
  v_result_rows jsonb := '[]'::jsonb;
begin
  perform private.finance_income_assert_items_with_limit(p_items, case when p_document_type = 'invoice' then 500 else 150 end);
  if p_document_type not in ('invoice', 'bill') then
    raise exception '不支援的補件表單類型'
      using errcode = '22023';
  end if;

  for v_item in
    select item_value
    from pg_catalog.jsonb_array_elements(p_items) item_value
    order by item_value ->> 'id'
  loop
    v_item_key := v_item ->> 'client_item_key';
    v_id := pg_catalog.btrim(coalesce(v_item ->> 'id', ''));
    v_comment := coalesce(pg_catalog.btrim(v_item ->> 'comment'), '');
    v_files := coalesce(v_item -> 'files', '[]'::jsonb);
    v_patch := coalesce(v_item -> 'patch', '{}'::jsonb);

    -- APPROVAL_REVISION_V2_EXPECTED_ROW_VERSION_SHAPE
    if pg_catalog.jsonb_typeof(
         v_item -> 'expected_row_version'
       ) <> 'number' then
      raise exception
        '補件預期資料版本不完整，請重新載入後再處理：%',
        v_id
        using errcode = '40001';
    end if;
    if coalesce(v_item ->> 'expected_row_version', '') !~
       '^[1-9][0-9]{0,18}$' then
      raise exception
        '補件預期資料版本不完整，請重新載入後再處理：%',
        v_id
        using errcode = '40001';
    end if;
    if (v_item ->> 'expected_row_version')::numeric >
       9223372036854775807::numeric then
      raise exception
        '補件預期資料版本超出允許範圍，請重新載入後再處理：%',
        v_id
        using errcode = '40001';
    end if;
    v_expected_row_version :=
      (v_item ->> 'expected_row_version')::bigint;

    if v_id = '' then
      raise exception '補件資料缺少表單 ID'
        using errcode = '22023';
    end if;
    if v_comment = '' then
      raise exception '補件重新送出必須填寫說明'
        using errcode = '22023';
    end if;
    if pg_catalog.jsonb_typeof(v_files) <> 'array'
       or pg_catalog.jsonb_array_length(v_files) > 20 then
      raise exception '補件附件格式錯誤或超過 20 個'
        using errcode = '22023';
    end if;
    if pg_catalog.jsonb_typeof(v_patch) <> 'object' then
      raise exception '補件 patch 必須是 JSON 物件'
        using errcode = '22023';
    end if;

    if p_document_type = 'invoice' then
      if exists (
        select 1
        from pg_catalog.jsonb_object_keys(v_patch) patch_key
        where patch_key not in (
          'buyer',
          'description',
          'tax_id',
          'invoice_identifier_type',
          'invoice_item_type',
          'payer_type',
          'funding_source',
          'service_period',
          'contract_no',
          'amount',
          'tax',
          'total'
        )
      ) then
        raise exception '發票補件包含不允許修改的欄位'
          using errcode = '22023';
      end if;
      if v_patch ? 'buyer'
         and coalesce(pg_catalog.btrim(v_patch ->> 'buyer'), '') = '' then
        raise exception '發票補件的買受人不可為空白'
          using errcode = '22023';
      end if;

      select invoice_row.*
        into v_invoice
      from public.invoices invoice_row
      where invoice_row.tenant_id = p_tenant_id
        and invoice_row.data_environment = p_data_environment
        and invoice_row.id = v_id
      for update;

      if not found then
        raise exception '發票不存在或不屬於目前租戶：%', v_id
          using errcode = 'P0002';
      end if;
      -- APPROVAL_REVISION_V2_LOCKED_ROW_VERSION_CAS
      if v_invoice.row_version is distinct from
         v_expected_row_version then
        raise exception
          '發票內容已被其他操作更新，請重新載入後再處理：%',
          v_id
          using errcode = '40001';
      end if;
      if v_invoice.applicant_id <> p_actor_finance_user_id then
        raise exception '只有原申請人可以重新送出發票補件：%', v_id
          using errcode = '42501';
      end if;
      if v_invoice.posting_locked_at is not null
         or v_invoice.voided_at is not null
         or v_invoice.revenue_posted is true
         or v_invoice.approval_status in (
           'completed',
           'delivered',
           'rejected',
           'cancelled'
         ) then
        raise exception '發票已結案或入帳，不能補件：%', v_id
          using errcode = '55000';
      end if;

      v_steps := v_invoice.steps;
      v_active_index := private.finance_income_active_step_index(v_steps);
      v_step := case
        when v_active_index is null then null
        else v_steps -> v_active_index
      end;
      if v_active_index is null
         or private.finance_income_step_role(v_step) <> 'applicant_revision'
         or private.finance_income_step_user_id(v_step) not in (
           '',
           p_actor_finance_user_id
         ) then
        raise exception '發票目前不是申請人補件步驟：%', v_id
          using errcode = '55000';
      end if;

      v_amount := v_invoice.amount;
      v_tax := v_invoice.tax;
      v_total := v_invoice.total;
      if v_patch ? 'amount' then
        if coalesce(v_patch ->> 'amount', '') !~
           '^[0-9]+([.][0-9]{1,2})?$' then
          raise exception '發票補件未稅金額格式錯誤：%', v_id
            using errcode = '22003';
        end if;
        v_amount := (v_patch ->> 'amount')::numeric;
      end if;
      if v_patch ? 'tax' then
        if coalesce(v_patch ->> 'tax', '') !~
           '^[0-9]+([.][0-9]{1,2})?$' then
          raise exception '發票補件稅額格式錯誤：%', v_id
            using errcode = '22003';
        end if;
        v_tax := (v_patch ->> 'tax')::numeric;
      end if;
      if v_patch ? 'total' then
        if coalesce(v_patch ->> 'total', '') !~
           '^[0-9]+([.][0-9]{1,2})?$' then
          raise exception '發票補件含稅總額格式錯誤：%', v_id
            using errcode = '22003';
        end if;
        v_total := (v_patch ->> 'total')::numeric;
      end if;
      if pg_catalog.abs(v_total - (v_amount + v_tax)) > 0.01 then
        raise exception '發票補件後未稅金額加稅額不等於含稅總額：%', v_id
          using errcode = '23514';
      end if;
      if v_total > v_invoice.total then
        raise exception
          '發票補件不可提高原申請金額；金額增加請撤回後重新送單：%',
          v_id
          using errcode = '23514';
      end if;

      v_identifier_type := v_invoice.invoice_identifier_type;
      if v_patch ? 'invoice_identifier_type' then
        v_identifier_type := public.normalize_invoice_identifier_type(
          v_patch ->> 'invoice_identifier_type'
        );
        if v_identifier_type not in (
          '電子發票',
          '統一編號',
          '電子發票（載具）',
          '領據'
        ) then
          raise exception '發票補件開立方式不支援：%', v_id
            using errcode = '23514';
        end if;
      end if;

      v_step_updated := private.finance_income_append_step_action(
        v_step,
        p_actor_finance_user_id,
        p_actor_name,
        '補件完成並重新送出',
        v_comment,
        v_files
      ) || pg_catalog.jsonb_build_object('a', 'approved');
      v_steps := pg_catalog.jsonb_set(
        v_steps,
        array[v_active_index::text],
        v_step_updated,
        false
      );
      v_status := private.finance_income_status_from_steps(v_steps);

      update public.invoices invoice_row
         set steps = v_steps,
             approval_status = v_status ->> 'approval_status',
             approval_step = (v_status ->> 'approval_step')::int,
             buyer = case
               when v_patch ? 'buyer'
                 then nullif(pg_catalog.btrim(v_patch ->> 'buyer'), '')
               else invoice_row.buyer
             end,
             description = case
               when v_patch ? 'description'
                 then nullif(pg_catalog.btrim(v_patch ->> 'description'), '')
               else invoice_row.description
             end,
             tax_id = case
               when v_patch ? 'tax_id'
                 then nullif(pg_catalog.btrim(v_patch ->> 'tax_id'), '')
               else invoice_row.tax_id
             end,
             invoice_identifier_type = v_identifier_type,
             invoice_item_type = case
               when v_patch ? 'invoice_item_type'
                 then nullif(
                   pg_catalog.btrim(v_patch ->> 'invoice_item_type'),
                   ''
                 )
               else invoice_row.invoice_item_type
             end,
             payer_type = case
               when v_patch ? 'payer_type'
                 then nullif(pg_catalog.btrim(v_patch ->> 'payer_type'), '')
               else invoice_row.payer_type
             end,
             funding_source = case
               when v_patch ? 'funding_source'
                 then nullif(pg_catalog.btrim(v_patch ->> 'funding_source'), '')
               else invoice_row.funding_source
             end,
             service_period = case
               when v_patch ? 'service_period'
                 then nullif(pg_catalog.btrim(v_patch ->> 'service_period'), '')
               else invoice_row.service_period
             end,
             contract_no = case
               when v_patch ? 'contract_no'
                 then nullif(pg_catalog.btrim(v_patch ->> 'contract_no'), '')
               else invoice_row.contract_no
             end,
             amount = v_amount,
             tax = v_tax,
             total = v_total,
             updated_at = pg_catalog.now()
       where invoice_row.tenant_id = p_tenant_id
         and invoice_row.data_environment = p_data_environment
         and invoice_row.id = v_id;
    else
      if exists (
        select 1
        from pg_catalog.jsonb_object_keys(v_patch) patch_key
        where patch_key not in (
          'item',
          'item_key',
          'payer_name',
          'service_period',
          'due_date',
          'method',
          'note',
          'amount'
        )
      ) then
        raise exception '繳費單補件包含不允許修改的欄位'
          using errcode = '22023';
      end if;
      if v_patch ? 'item'
         and coalesce(pg_catalog.btrim(v_patch ->> 'item'), '') = '' then
        raise exception '繳費單補件的項目名稱不可為空白'
          using errcode = '22023';
      end if;
      if v_patch ? 'payer_name'
         and coalesce(pg_catalog.btrim(v_patch ->> 'payer_name'), '') = '' then
        raise exception '繳費單補件的繳費人不可為空白'
          using errcode = '22023';
      end if;

      select bill_row.*
        into v_bill
      from public.bills bill_row
      where bill_row.tenant_id = p_tenant_id
        and bill_row.data_environment = p_data_environment
        and bill_row.id = v_id
      for update;

      if not found then
        raise exception '繳費單不存在或不屬於目前租戶：%', v_id
          using errcode = 'P0002';
      end if;
      -- APPROVAL_REVISION_V2_LOCKED_ROW_VERSION_CAS
      if v_bill.row_version is distinct from
         v_expected_row_version then
        raise exception
          '繳費單內容已被其他操作更新，請重新載入後再處理：%',
          v_id
          using errcode = '40001';
      end if;
      if v_bill.applicant_id <> p_actor_finance_user_id then
        raise exception '只有原申請人可以重新送出繳費單補件：%', v_id
          using errcode = '42501';
      end if;
      if v_bill.voided_at is not null
         or v_bill.status in ('paid', 'void')
         or v_bill.approval_status in ('completed', 'rejected', 'cancelled') then
        raise exception '繳費單已結案，不能補件：%', v_id
          using errcode = '55000';
      end if;

      v_steps := v_bill.steps;
      v_active_index := private.finance_income_active_step_index(v_steps);
      v_step := case
        when v_active_index is null then null
        else v_steps -> v_active_index
      end;
      if v_active_index is null
         or private.finance_income_step_role(v_step) <> 'applicant_revision'
         or private.finance_income_step_user_id(v_step) not in (
           '',
           p_actor_finance_user_id
         ) then
        raise exception '繳費單目前不是申請人補件步驟：%', v_id
          using errcode = '55000';
      end if;

      v_amount := v_bill.amount;
      if v_patch ? 'amount' then
        if coalesce(v_patch ->> 'amount', '') !~
           '^[0-9]+([.][0-9]{1,2})?$' then
          raise exception '繳費單補件金額格式錯誤：%', v_id
            using errcode = '22003';
        end if;
        v_amount := (v_patch ->> 'amount')::numeric;
      end if;
      if v_amount <= 0 then
        raise exception '繳費單補件金額必須大於零：%', v_id
          using errcode = '23514';
      end if;
      if v_amount > v_bill.amount then
        raise exception
          '繳費單補件不可提高原申請金額；金額增加請撤回後重新送單：%',
          v_id
          using errcode = '23514';
      end if;

      v_step_updated := private.finance_income_append_step_action(
        v_step,
        p_actor_finance_user_id,
        p_actor_name,
        '補件完成並重新送出',
        v_comment,
        v_files
      ) || pg_catalog.jsonb_build_object('a', 'approved');
      v_steps := pg_catalog.jsonb_set(
        v_steps,
        array[v_active_index::text],
        v_step_updated,
        false
      );
      v_status := private.finance_income_status_from_steps(v_steps);

      update public.bills bill_row
         set steps = v_steps,
             approval_status = v_status ->> 'approval_status',
             approval_step = (v_status ->> 'approval_step')::int,
             item = case
               when v_patch ? 'item'
                 then nullif(pg_catalog.btrim(v_patch ->> 'item'), '')
               else bill_row.item
             end,
             item_key = case
               when v_patch ? 'item_key'
                 then nullif(pg_catalog.btrim(v_patch ->> 'item_key'), '')
               else bill_row.item_key
             end,
             payer_name = case
               when v_patch ? 'payer_name'
                 then nullif(pg_catalog.btrim(v_patch ->> 'payer_name'), '')
               else bill_row.payer_name
             end,
             service_period = case
               when v_patch ? 'service_period'
                 then nullif(pg_catalog.btrim(v_patch ->> 'service_period'), '')
               else bill_row.service_period
             end,
             due_date = case
               when v_patch ? 'due_date'
                 then nullif(v_patch ->> 'due_date', '')::date
               else bill_row.due_date
             end,
             method = case
               when v_patch ? 'method'
                 then nullif(pg_catalog.btrim(v_patch ->> 'method'), '')
               else bill_row.method
             end,
             note = case
               when v_patch ? 'note'
                 then nullif(pg_catalog.btrim(v_patch ->> 'note'), '')
               else bill_row.note
             end,
             amount = v_amount
       where bill_row.tenant_id = p_tenant_id
         and bill_row.data_environment = p_data_environment
         and bill_row.id = v_id;
    end if;

    v_result_rows := v_result_rows || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'client_item_key', v_item_key,
        'id', v_id,
        'approval_status', v_status ->> 'approval_status',
        'approval_step', (v_status ->> 'approval_step')::int
      )
    );
  end loop;

  return v_result_rows;
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_resubmit_invoice_applicant_revision_v2(p_idempotency_key text, p_items jsonb, p_data_environment text DEFAULT 'production'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_actor public.finance_users%rowtype;
  v_environment text := pg_catalog.lower(coalesce(p_data_environment, 'production'));
  v_digest text;
  v_cached jsonb;
  v_rows jsonb;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception '請先登入後再重新送出發票補件'
      using errcode = '42501';
  end if;
  if v_environment not in ('production', 'test') then
    raise exception '資料環境只允許 production 或 test'
      using errcode = '22023';
  end if;

  v_tenant_id := public.current_tenant_id();
  select finance_user.*
    into v_actor
  from public.finance_users finance_user
  where finance_user.tenant_id = v_tenant_id
    and finance_user.auth_user_id = auth.uid()
    and finance_user.active is true
  order by finance_user.created_at, finance_user.id
  limit 1;
  if not found then
    raise exception '目前登入帳號沒有此租戶的有效財務人員身分'
      using errcode = '42501';
  end if;

  perform private.finance_income_assert_items_with_limit(p_items, 500);
  v_digest := private.finance_income_request_digest(
    pg_catalog.jsonb_build_object(
      'operation', 'invoice_resubmit',
      'environment', v_environment,
      'items', p_items
    )
  );
  v_cached := private.finance_income_begin_operation(
    v_tenant_id,
    v_environment,
    'invoice_resubmit',
    p_idempotency_key,
    v_digest,
    v_actor.id
  );
  if v_cached is not null then
    return v_cached || pg_catalog.jsonb_build_object(
      'idempotent_replay',
      true
    );
  end if;

  v_rows := private.finance_income_resubmit_revision_rows_v2(
    'invoice',
    v_tenant_id,
    v_actor.id,
    v_actor.name,
    v_environment,
    p_items
  );
  v_result := pg_catalog.jsonb_build_object(
    'ok', true,
    'idempotent_replay', false,
    'document_type', 'invoice',
    'action', 'applicant_revision_resubmit',
    'idempotency_key', p_idempotency_key,
    'count', pg_catalog.jsonb_array_length(v_rows),
    'rows', v_rows
  );
  perform private.finance_income_finish_operation(
    v_tenant_id,
    v_environment,
    'invoice_resubmit',
    p_idempotency_key,
    v_result
  );
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_resubmit_bill_applicant_revision_v2(p_idempotency_key text, p_items jsonb, p_data_environment text DEFAULT 'production'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '5s'
AS $function$
declare
  v_tenant_id uuid;
  v_actor public.finance_users%rowtype;
  v_environment text := pg_catalog.lower(coalesce(p_data_environment, 'production'));
  v_digest text;
  v_cached jsonb;
  v_rows jsonb;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception '請先登入後再重新送出繳費單補件'
      using errcode = '42501';
  end if;
  if v_environment not in ('production', 'test') then
    raise exception '資料環境只允許 production 或 test'
      using errcode = '22023';
  end if;

  v_tenant_id := public.current_tenant_id();
  select finance_user.*
    into v_actor
  from public.finance_users finance_user
  where finance_user.tenant_id = v_tenant_id
    and finance_user.auth_user_id = auth.uid()
    and finance_user.active is true
  order by finance_user.created_at, finance_user.id
  limit 1;
  if not found then
    raise exception '目前登入帳號沒有此租戶的有效財務人員身分'
      using errcode = '42501';
  end if;

  perform private.finance_income_assert_items_with_limit(p_items, 150);  v_digest := private.finance_income_request_digest(
    pg_catalog.jsonb_build_object(
      'operation', 'bill_resubmit',
      'environment', v_environment,
      'items', p_items
    )
  );
  v_cached := private.finance_income_begin_operation(
    v_tenant_id,
    v_environment,
    'bill_resubmit',
    p_idempotency_key,
    v_digest,
    v_actor.id
  );
  if v_cached is not null then
    return v_cached || pg_catalog.jsonb_build_object(
      'idempotent_replay',
      true
    );
  end if;


  -- APPROVAL_V2_BILL_REVISION_MEMBERSHIP_TABLE_LOCK
  -- CONCURRENCY WARNING: this deliberately serializes bill v2 revisions
  -- across all tenants. Contention fails within lock_timeout=5s for retry.
  lock table public.bills in share row exclusive mode;


  -- BILL_BATCH_REVISION_COMPLETE_SIBLINGS_GUARD_V1
  -- BILL_BATCH_REVISION_SELECTED_IDS_SCOPE_GUARD_V1
  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_items)
      requested_item(item_value)
    where nullif(
      pg_catalog.btrim(requested_item.item_value ->> 'id'),
      ''
    ) is null
  ) then
    raise exception '補件資料缺少繳費單 ID，已停止整批重新送出'
      using errcode = '55000';
  end if;

  if (
    select pg_catalog.count(distinct pg_catalog.btrim(
      requested_item.item_value ->> 'id'
    ))
    from pg_catalog.jsonb_array_elements(p_items)
      requested_item(item_value)
  ) <> pg_catalog.jsonb_array_length(p_items) then
    raise exception '同一次補件不可包含重複的繳費單 ID'
      using errcode = '55000';
  end if;

  if (
    select pg_catalog.count(*)
    from public.bills selected_row
    where selected_row.tenant_id = v_tenant_id
      and selected_row.data_environment = v_environment
      and selected_row.id in (
        select pg_catalog.btrim(requested_item.item_value ->> 'id')
        from pg_catalog.jsonb_array_elements(p_items)
          requested_item(item_value)
      )
  ) <> pg_catalog.jsonb_array_length(p_items) then
    raise exception
      '部分補件繳費單不存在或不屬於目前租戶，已停止整批重新送出'
      using errcode = '55000';
  end if;

  if exists (
    with selected_bill_rows as (
      select bill_row.id,
             nullif(pg_catalog.btrim(bill_row.batch_id), '') as batch_id
      from public.bills bill_row
      where bill_row.tenant_id = v_tenant_id
        and bill_row.data_environment = v_environment
        and bill_row.id in (
          select pg_catalog.btrim(requested_item.item_value ->> 'id')
          from pg_catalog.jsonb_array_elements(p_items)
            requested_item(item_value)
        )
    ),
    selected_batches as (
      select selected_bill.batch_id,
             pg_catalog.count(*) as selected_count
      from selected_bill_rows selected_bill
      where selected_bill.batch_id is not null
      group by selected_bill.batch_id
    )
    select 1
    from selected_batches selected_batch
    where selected_batch.selected_count <> (
      select pg_catalog.count(*)
      from public.bills sibling_row
      where sibling_row.tenant_id = v_tenant_id
        and sibling_row.data_environment = v_environment
        and nullif(pg_catalog.btrim(sibling_row.batch_id), '') =
            selected_batch.batch_id
    )
  ) then
    raise exception
      '同一批繳費單必須完整補件重新送出，請重新整理後再試'
      using errcode = '55000';
  end if;

  v_rows := private.finance_income_resubmit_revision_rows_v2(
    'bill',
    v_tenant_id,
    v_actor.id,
    v_actor.name,
    v_environment,
    p_items
  );
  v_result := pg_catalog.jsonb_build_object(
    'ok', true,
    'idempotent_replay', false,
    'document_type', 'bill',
    'action', 'applicant_revision_resubmit',
    'idempotency_key', p_idempotency_key,
    'count', pg_catalog.jsonb_array_length(v_rows),
    'rows', v_rows
  );
  perform private.finance_income_finish_operation(
    v_tenant_id,
    v_environment,
    'bill_resubmit',
    p_idempotency_key,
    v_result
  );
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_invoice_act_active_step_v2(p_invoice_ids text[], p_action text, p_idempotency_key text, p_comment text DEFAULT NULL::text, p_files jsonb DEFAULT '[]'::jsonb, p_add_sign_finance_user_id text DEFAULT NULL::text, p_expected_steps jsonb DEFAULT '{}'::jsonb, p_patches jsonb DEFAULT '{}'::jsonb, p_data_environment text DEFAULT 'production'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_actor public.finance_users%rowtype;
  v_target public.finance_users%rowtype;
  v_environment text :=
    pg_catalog.lower(coalesce(p_data_environment, 'production'));
  v_action text := pg_catalog.lower(coalesce(p_action, ''));
  v_comment text := coalesce(pg_catalog.btrim(p_comment), '');
  v_digest text;
  v_cached jsonb;
  v_invoice_id text;
  v_invoice public.invoices%rowtype;
  v_steps jsonb;
  v_step jsonb;
  v_expected_step jsonb;
  v_patch jsonb;
  v_step_updated jsonb;
  v_active_index int;
  v_previous_index int;
  v_previous_step jsonb;
  v_role_key text;
  v_status jsonb;
  v_add_step jsonb;
  v_revision_step jsonb;
  v_patch_amount numeric;
  v_patch_tax numeric;
  v_patch_total numeric;
  v_result_rows jsonb := '[]'::jsonb;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception '請先登入後再處理發票簽核'
      using errcode = '42501';
  end if;

  if v_environment not in ('production', 'test') then
    raise exception '資料環境只允許 production 或 test'
      using errcode = '22023';
  end if;

  if v_action not in ('approve', 'return', 'reject', 'add_sign') then
    raise exception
      '簽核動作只允許 approve、return、reject 或 add_sign'
      using errcode = '22023';
  end if;

  if p_invoice_ids is null
     or pg_catalog.cardinality(p_invoice_ids) < 1
     or pg_catalog.cardinality(p_invoice_ids) > 500 then
    raise exception '每次必須處理 1 到 500 張發票'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from pg_catalog.unnest(p_invoice_ids) invoice_id
    where coalesce(pg_catalog.btrim(invoice_id), '') = ''
  ) then
    raise exception '發票 ID 不可為空白'
      using errcode = '22023';
  end if;

  if pg_catalog.cardinality(p_invoice_ids) <> (
    select pg_catalog.count(distinct invoice_id)
    from pg_catalog.unnest(p_invoice_ids) invoice_id
  ) then
    raise exception '同一次簽核不可包含重複的發票 ID'
      using errcode = '23505';
  end if;

  if pg_catalog.jsonb_typeof(coalesce(p_files, '[]'::jsonb)) <>
       'array'
     or pg_catalog.jsonb_array_length(
       coalesce(p_files, '[]'::jsonb)
     ) > 20 then
    raise exception '附件資料格式錯誤或超過 20 個'
      using errcode = '22023';
  end if;

  if pg_catalog.jsonb_typeof(coalesce(p_expected_steps, '{}'::jsonb)) <>
       'object'
     or (
       select pg_catalog.count(*)
       from pg_catalog.jsonb_object_keys(
         coalesce(p_expected_steps, '{}'::jsonb)
       )
     ) <> pg_catalog.cardinality(p_invoice_ids)
     or exists (
       select 1
       from pg_catalog.jsonb_object_keys(
         coalesce(p_expected_steps, '{}'::jsonb)
       ) as expected_invoice(expected_invoice_id)
       where not (expected_invoice.expected_invoice_id = any(p_invoice_ids))
     ) then
    raise exception '發票預期關卡資料不完整，請重新整理後再處理'
      using errcode = '40001';
  end if;

  -- APPROVAL_V2_EXPECTED_ROW_VERSION_SHAPE
  if exists (
    select 1
    from pg_catalog.jsonb_each(
      coalesce(p_expected_steps, '{}'::jsonb)
    ) expected_row(expected_id, expected_value)
    where pg_catalog.jsonb_typeof(expected_row.expected_value) <> 'object'
       or pg_catalog.jsonb_typeof(
            expected_row.expected_value -> 'row_version'
          ) <> 'number'
       or pg_catalog.jsonb_typeof(
            expected_row.expected_value -> 'active_step_index'
          ) <> 'number'
  ) then
    raise exception
      '發票預期資料版本不完整，請重新載入後再處理'
      using errcode = '40001';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_each(
      coalesce(p_expected_steps, '{}'::jsonb)
    ) expected_row(expected_id, expected_value)
    where coalesce(
            expected_row.expected_value ->> 'row_version',
            ''
          ) !~ '^[1-9][0-9]{0,18}$'
       or coalesce(
            expected_row.expected_value ->> 'active_step_index',
            ''
          ) !~ '^(0|[1-9][0-9]{0,9})$'
  ) then
    raise exception
      '發票預期資料版本不完整，請重新載入後再處理'
      using errcode = '40001';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_each(
      coalesce(p_expected_steps, '{}'::jsonb)
    ) expected_row(expected_id, expected_value)
    where (expected_row.expected_value ->> 'row_version')::numeric >
            9223372036854775807::numeric
       or (expected_row.expected_value ->> 'active_step_index')::numeric >
            2147483647::numeric
  ) then
    raise exception
      '發票預期資料版本超出允許範圍，請重新載入後再處理'
      using errcode = '40001';
  end if;

  if pg_catalog.jsonb_typeof(coalesce(p_patches, '{}'::jsonb)) <>
       'object'
     or exists (
       select 1
       from pg_catalog.jsonb_object_keys(
         coalesce(p_patches, '{}'::jsonb)
       ) as patch_invoice(patch_invoice_id)
       where not (patch_invoice.patch_invoice_id = any(p_invoice_ids))
     ) then
    raise exception '發票核准修訂資料格式錯誤'
      using errcode = '22023';
  end if;

  if v_action in ('return', 'reject', 'add_sign')
     and v_comment = '' then
    raise exception '退回、不通過或加簽必須填寫原因'
      using errcode = '22023';
  end if;

  if v_action = 'add_sign'
     and coalesce(p_add_sign_finance_user_id, '') = '' then
    raise exception '加簽必須指定人員'
      using errcode = '22023';
  end if;

  v_tenant_id := public.current_tenant_id();

  select finance_user.*
    into v_actor
  from public.finance_users finance_user
  where finance_user.tenant_id = v_tenant_id
    and finance_user.auth_user_id = auth.uid()
    and finance_user.active is true
  order by finance_user.created_at, finance_user.id
  limit 1;

  if not found then
    raise exception '目前登入帳號沒有此租戶的有效財務人員身分'
      using errcode = '42501';
  end if;
  v_digest := private.finance_income_request_digest(
    pg_catalog.jsonb_build_object(
      'operation', 'invoice_action',
      'environment', v_environment,
      'invoice_ids', pg_catalog.to_jsonb(p_invoice_ids),
      'action', v_action,
      'comment', v_comment,
      'files', coalesce(p_files, '[]'::jsonb),
      'add_sign_finance_user_id', p_add_sign_finance_user_id,
      'expected_steps', coalesce(p_expected_steps, '{}'::jsonb),
      'patches', coalesce(p_patches, '{}'::jsonb)
    )
  );

  v_cached := private.finance_income_begin_operation(
    v_tenant_id,
    v_environment,
    'invoice_action',
    p_idempotency_key,
    v_digest,
    v_actor.id
  );

  if v_cached is not null then
    return v_cached || pg_catalog.jsonb_build_object(
      'idempotent_replay',
      true
    );
  end if;


  if v_action = 'add_sign' then
    select finance_user.*
      into v_target
    from public.finance_users finance_user
    where finance_user.tenant_id = v_tenant_id
      and finance_user.id = p_add_sign_finance_user_id
      and finance_user.active is true
    limit 1;

    if not found then
      raise exception '指定的加簽人不存在、已停用或不屬於目前租戶'
        using errcode = '23503';
    end if;

    if v_target.id = v_actor.id then
      raise exception '不可加簽自己'
        using errcode = '22023';
    end if;
  end if;

  for v_invoice_id in
    select invoice_id
    from pg_catalog.unnest(p_invoice_ids) invoice_id
    order by invoice_id
  loop
    select invoice_row.*
      into v_invoice
    from public.invoices invoice_row
    where invoice_row.tenant_id = v_tenant_id
      and invoice_row.data_environment = v_environment
      and invoice_row.id = v_invoice_id
    for update;

    if not found then
      raise exception '發票不存在或不屬於目前租戶：%', v_invoice_id
        using errcode = 'P0002';
    end if;

    -- APPROVAL_V2_LOCKED_ROW_VERSION_CAS
    v_expected_step := p_expected_steps -> v_invoice_id;
    if v_invoice.row_version is distinct from
       (v_expected_step ->> 'row_version')::bigint then
      raise exception
        '發票內容已被其他操作更新，請重新載入後再處理：%',
        v_invoice_id
        using errcode = '40001';
    end if;

    if v_invoice.posting_locked_at is not null
       or v_invoice.voided_at is not null
       or v_invoice.revenue_posted is true
       or v_invoice.status in ('paid', 'void')
       or v_invoice.approval_status in (
         'completed',
         'delivered',
         'rejected',
         'cancelled'
       ) then
      raise exception '發票已結案、作廢或入帳，不能再執行簽核：%',
        v_invoice_id
        using errcode = '55000';
    end if;

    v_steps := coalesce(v_invoice.steps, '[]'::jsonb);
    if pg_catalog.jsonb_typeof(v_steps) <> 'array' then
      raise exception '發票簽核步驟格式錯誤：%', v_invoice_id
        using errcode = '22023';
    end if;

    v_active_index :=
      private.finance_income_active_step_index(v_steps);
    if v_active_index is null then
      raise exception '發票沒有待處理的簽核步驟：%', v_invoice_id
        using errcode = '55000';
    end if;

    v_step := v_steps -> v_active_index;
    v_role_key := private.finance_income_step_role(v_step);
    v_expected_step := p_expected_steps -> v_invoice_id;

    if pg_catalog.jsonb_typeof(v_expected_step) <> 'object'
       or coalesce((v_expected_step ->> 'active_step_index')::int, -1)
            <> v_active_index
       or coalesce(v_expected_step ->> 'role_key', '')
            <> coalesce(v_role_key, '')
       or coalesce(v_expected_step ->> 'finance_user_id', '')
            <> coalesce(private.finance_income_step_user_id(v_step), '')
       or pg_catalog.lower(
            coalesce(v_expected_step ->> 'email', '')
          ) <> pg_catalog.lower(coalesce(v_step ->> 'email', ''))
       or coalesce(v_expected_step ->> 'approval_status', '')
            <> coalesce(v_invoice.approval_status, '') then
      raise exception
        '發票簽核關卡已被其他操作更新，請重新整理後再處理：%',
        v_invoice_id
        using errcode = '40001';
    end if;

    if v_role_key = 'applicant_revision' then
      raise exception
        '發票目前為申請人補件，請使用補件完成並重新送出功能：%',
        v_invoice_id
        using errcode = '55000';
    end if;

    if not private.finance_invoice_actor_can_act(
      v_tenant_id,
      v_invoice,
      v_active_index,
      v_step,
      v_actor.id,
      v_actor.email,
      v_actor.role
    ) then
      raise exception '您不是發票目前待簽步驟的有效處理人：%',
        v_invoice_id
        using errcode = '42501';
    end if;

    v_patch := coalesce(p_patches -> v_invoice_id, '{}'::jsonb);
    if pg_catalog.jsonb_typeof(v_patch) <> 'object'
       or exists (
         select 1
         from pg_catalog.jsonb_object_keys(v_patch) as patch_field(patch_key)
         where patch_field.patch_key not in (
           'description',
           'amount',
           'tax',
           'total',
           'invoice_item_type',
           'revenue_account_code',
           'revenue_account_name',
           'revenue_rule_snapshot'
         )
       ) then
      raise exception '發票核准修訂包含不允許的欄位：%', v_invoice_id
        using errcode = '22023';
    end if;

    if v_patch <> '{}'::jsonb then
      if v_action not in ('approve', 'add_sign')
         or v_actor.role not in ('accountant', 'admin_director', 'ceo') then
        raise exception '目前角色或動作不可修訂發票會計明細：%',
          v_invoice_id
          using errcode = '42501';
      end if;

      if not (
        v_patch ?& array[
          'description',
          'amount',
          'tax',
          'total',
          'invoice_item_type',
          'revenue_account_code',
          'revenue_account_name',
          'revenue_rule_snapshot'
        ]
      ) then
        raise exception '發票核准修訂欄位不完整：%', v_invoice_id
          using errcode = '22023';
      end if;

      v_patch_amount := (v_patch ->> 'amount')::numeric;
      v_patch_tax := (v_patch ->> 'tax')::numeric;
      v_patch_total := (v_patch ->> 'total')::numeric;

      if v_patch_amount < 0
         or v_patch_tax < 0
         or v_patch_total < 0
         or pg_catalog.abs(
           (v_patch_amount + v_patch_tax) - v_patch_total
         ) > 0.01
         or pg_catalog.length(v_patch ->> 'description') > 2000
         or coalesce(pg_catalog.btrim(v_patch ->> 'invoice_item_type'), '') = ''
         or coalesce(
           pg_catalog.btrim(v_patch ->> 'revenue_account_code'),
           ''
         ) !~ '^[0-9]{4,8}$'
         or coalesce(
           pg_catalog.btrim(v_patch ->> 'revenue_account_name'),
           ''
         ) = ''
         or pg_catalog.jsonb_typeof(
           v_patch -> 'revenue_rule_snapshot'
         ) <> 'object' then
        raise exception '發票核准修訂的金額或收入科目格式錯誤：%',
          v_invoice_id
          using errcode = '22023';
      end if;
    end if;

    if v_action in ('approve', 'add_sign') then
      v_step_updated := private.finance_income_append_step_action(
        v_step,
        v_actor.id,
        v_actor.name,
        case
          when v_action = 'add_sign' then '簽核通過並加簽'
          else '簽核通過'
        end,
        v_comment,
        p_files
      ) || pg_catalog.jsonb_build_object('a', 'approved');

      v_steps := pg_catalog.jsonb_set(
        v_steps,
        array[v_active_index::text],
        v_step_updated,
        false
      );

      if v_action = 'add_sign' then
        v_add_step := pg_catalog.jsonb_build_object(
          'r', '加簽：' || v_target.name,
          'rk', 'assigned_user',
          'uid', v_target.id,
          'n', '',
          'a', '',
          't', '',
          'c', '加簽原因：' || v_comment,
          'files', '[]'::jsonb,
          'status', 'pending_countersign',
          'requestedBy', v_actor.name
        );

        v_steps := pg_catalog.jsonb_insert(
          v_steps,
          array[v_active_index::text],
          v_add_step,
          true
        );
      end if;
    elsif v_action = 'reject' then
      v_step_updated := private.finance_income_append_step_action(
        v_step,
        v_actor.id,
        v_actor.name,
        '不通過',
        v_comment,
        p_files
      ) || pg_catalog.jsonb_build_object('a', 'rejected');

      v_steps := pg_catalog.jsonb_set(
        v_steps,
        array[v_active_index::text],
        v_step_updated,
        false
      );
    else
      v_previous_index := v_active_index - 1;
      while v_previous_index >= 0 loop
        v_previous_step := v_steps -> v_previous_index;
        exit when pg_catalog.lower(
          coalesce(v_previous_step ->> 'autoSkip', 'false')
        ) <> 'true';
        v_previous_index := v_previous_index - 1;
      end loop;

      if v_previous_index < 0 then
        raise exception '發票目前沒有可退回的上一關：%',
          v_invoice_id
          using errcode = '55000';
      end if;

      v_step_updated := private.finance_income_append_step_action(
        v_step,
        v_actor.id,
        v_actor.name,
        '退回上一關',
        v_comment,
        p_files
      );

      v_steps := pg_catalog.jsonb_set(
        v_steps,
        array[v_active_index::text],
        v_step_updated,
        false
      );
      v_previous_step := v_steps -> v_previous_index;

      if private.finance_income_step_role(v_previous_step) =
         'applicant_submit' then
        if coalesce(v_invoice.applicant_id, '') = '' then
          raise exception '發票缺少原申請人，無法建立補件關卡：%',
            v_invoice_id
            using errcode = '55000';
        end if;

        v_revision_step := pg_catalog.jsonb_build_object(
          'r', '申請人補件後重新送出',
          'rk', 'applicant_revision',
          'uid', v_invoice.applicant_id,
          'n', '',
          'a', '',
          't', '',
          'c', '',
          'files', '[]'::jsonb,
          'status', 'pending_invoice_applicant'
        );

        v_revision_step := private.finance_income_append_step_action(
          v_revision_step,
          v_actor.id,
          v_actor.name,
          '退回上一關',
          v_comment,
          p_files
        ) - 'n' - 't';

        v_steps := pg_catalog.jsonb_insert(
          v_steps,
          array[v_active_index::text],
          v_revision_step,
          false
        );
      else
        v_previous_step := private.finance_income_append_step_action(
          v_previous_step - 'a' - 'n' - 't',
          v_actor.id,
          v_actor.name,
          '退回上一關',
          v_comment,
          p_files
        ) - 'a' - 'n' - 't';

        v_steps := pg_catalog.jsonb_set(
          v_steps,
          array[v_previous_index::text],
          v_previous_step,
          false
        );
      end if;
    end if;

    if v_action = 'reject' then
      v_status := pg_catalog.jsonb_build_object(
        'approval_status', 'rejected',
        'approval_step', v_active_index + 1
      );
    else
      v_status := private.finance_income_status_from_steps(v_steps);

      -- The legacy invoice UI distinguishes a fully approved invoice whose
      -- applicant-delivery step has completed from a generic completed flow.
      if v_status ->> 'approval_status' = 'completed'
         and exists (
           select 1
           from pg_catalog.jsonb_array_elements(v_steps) completed_step
           where private.finance_income_step_role(completed_step) =
             'applicant_invoice_delivery'
             and pg_catalog.lower(
               coalesce(completed_step ->> 'a', '')
             ) in ('approved', 'auto')
         ) then
        v_status := pg_catalog.jsonb_set(
          v_status,
          '{approval_status}',
          '"delivered"'::jsonb,
          false
        );
      end if;
    end if;

    update public.invoices invoice_row
       set steps = v_steps,
           approval_status = v_status ->> 'approval_status',
           approval_step =
             (v_status ->> 'approval_step')::int,
           description = case
             when v_patch <> '{}'::jsonb
               then v_patch ->> 'description'
             else v_invoice.description
           end,
           amount = case
             when v_patch <> '{}'::jsonb then v_patch_amount
             else v_invoice.amount
           end,
           tax = case
             when v_patch <> '{}'::jsonb then v_patch_tax
             else v_invoice.tax
           end,
           total = case
             when v_patch <> '{}'::jsonb then v_patch_total
             else v_invoice.total
           end,
           invoice_item_type = case
             when v_patch <> '{}'::jsonb
               then v_patch ->> 'invoice_item_type'
             else v_invoice.invoice_item_type
           end,
           revenue_account_code = case
             when v_patch <> '{}'::jsonb
               then v_patch ->> 'revenue_account_code'
             else v_invoice.revenue_account_code
           end,
           revenue_account_name = case
             when v_patch <> '{}'::jsonb
               then v_patch ->> 'revenue_account_name'
             else v_invoice.revenue_account_name
           end,
           revenue_rule_snapshot = case
             when v_patch <> '{}'::jsonb
               then v_patch -> 'revenue_rule_snapshot'
             else v_invoice.revenue_rule_snapshot
           end,
           updated_at = pg_catalog.now()
     where invoice_row.tenant_id = v_tenant_id
       and invoice_row.data_environment = v_environment
       and invoice_row.id = v_invoice_id;

    if not found then
      raise exception '發票簽核狀態寫入失敗：%', v_invoice_id
        using errcode = '55000';
    end if;

    v_result_rows := v_result_rows ||
      pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'id', v_invoice_id,
          'no', v_invoice.no,
          'batch_id', v_invoice.batch_id,
          'action', v_action,
          'active_role_key', v_role_key,
          'approval_status', v_status ->> 'approval_status',
          'approval_step',
            (v_status ->> 'approval_step')::int
        )
      );
  end loop;

  v_result := pg_catalog.jsonb_build_object(
    'ok', true,
    'idempotent_replay', false,
    'document_type', 'invoice',
    'action', v_action,
    'idempotency_key', p_idempotency_key,
    'count', pg_catalog.jsonb_array_length(v_result_rows),
    'rows', v_result_rows
  );

  perform private.finance_income_finish_operation(
    v_tenant_id,
    v_environment,
    'invoice_action',
    p_idempotency_key,
    v_result
  );

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_bill_act_active_step_v2(p_bill_ids text[], p_action text, p_idempotency_key text, p_comment text DEFAULT NULL::text, p_files jsonb DEFAULT '[]'::jsonb, p_add_sign_finance_user_id text DEFAULT NULL::text, p_expected_steps jsonb DEFAULT '{}'::jsonb, p_data_environment text DEFAULT 'production'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '5s'
AS $function$
declare
  v_tenant_id uuid;
  v_actor public.finance_users%rowtype;
  v_target public.finance_users%rowtype;
  v_environment text := pg_catalog.lower(coalesce(p_data_environment, 'production'));
  v_action text := pg_catalog.lower(coalesce(p_action, ''));
  v_comment text := coalesce(pg_catalog.btrim(p_comment), '');
  v_digest text;
  v_cached jsonb;
  v_bill_id text;
  v_bill public.bills%rowtype;
  v_steps jsonb;
  v_step jsonb;
  v_expected_step jsonb;
  v_step_updated jsonb;
  v_active_index int;
  v_previous_index int;
  v_previous_step jsonb;
  v_role_key text;
  v_status jsonb;
  v_add_step jsonb;
  v_revision_step jsonb;
  v_result_rows jsonb := '[]'::jsonb;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception '請先登入後再處理繳費單簽核'
      using errcode = '42501';
  end if;
  if v_environment not in ('production', 'test') then
    raise exception '資料環境只允許 production 或 test'
      using errcode = '22023';
  end if;
  if v_action not in ('approve', 'return', 'reject', 'add_sign') then
    raise exception '簽核動作只允許 approve、return、reject 或 add_sign'
      using errcode = '22023';
  end if;
  if p_bill_ids is null
     or pg_catalog.cardinality(p_bill_ids) < 1
     or pg_catalog.cardinality(p_bill_ids) > 150 then
    raise exception '每次必須處理 1 到 150 張繳費單'
      using errcode = '22023';
  end if;
  if pg_catalog.cardinality(p_bill_ids) <> (
    select pg_catalog.count(distinct bill_id)
    from pg_catalog.unnest(p_bill_ids) bill_id
  ) then
    raise exception '同一次簽核不可包含重複的繳費單 ID'
      using errcode = '23505';
  end if;
  if pg_catalog.jsonb_typeof(coalesce(p_files, '[]'::jsonb)) <> 'array'
     or pg_catalog.jsonb_array_length(coalesce(p_files, '[]'::jsonb)) > 20 then
    raise exception '附件資料格式錯誤或超過 20 個'
      using errcode = '22023';
  end if;
  -- APPROVAL_V2_EXPECTED_ROW_VERSION_SHAPE
  if pg_catalog.jsonb_typeof(
       coalesce(p_expected_steps, '{}'::jsonb)
     ) <> 'object'
     or (
       select pg_catalog.count(*)
       from pg_catalog.jsonb_object_keys(
         coalesce(p_expected_steps, '{}'::jsonb)
       )
     ) <> pg_catalog.cardinality(p_bill_ids)
     or exists (
       select 1
       from pg_catalog.jsonb_object_keys(
         coalesce(p_expected_steps, '{}'::jsonb)
       ) expected_id
       where not (expected_id = any(p_bill_ids))
     )
     or exists (
       select 1
       from pg_catalog.jsonb_each(
         coalesce(p_expected_steps, '{}'::jsonb)
       ) expected_row(expected_id, expected_value)
       where pg_catalog.jsonb_typeof(expected_row.expected_value) <> 'object'
          or pg_catalog.jsonb_typeof(
               expected_row.expected_value -> 'row_version'
             ) <> 'number'
          or pg_catalog.jsonb_typeof(
               expected_row.expected_value -> 'active_step_index'
             ) <> 'number'
     ) then
    raise exception
      '繳費單預期資料版本不完整，請重新載入後再處理'
      using errcode = '40001';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_each(
      coalesce(p_expected_steps, '{}'::jsonb)
    ) expected_row(expected_id, expected_value)
    where coalesce(
            expected_row.expected_value ->> 'row_version',
            ''
          ) !~ '^[1-9][0-9]{0,18}$'
       or coalesce(
            expected_row.expected_value ->> 'active_step_index',
            ''
          ) !~ '^(0|[1-9][0-9]{0,9})$'
  ) then
    raise exception
      '繳費單預期資料版本不完整，請重新載入後再處理'
      using errcode = '40001';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_each(
      coalesce(p_expected_steps, '{}'::jsonb)
    ) expected_row(expected_id, expected_value)
    where (expected_row.expected_value ->> 'row_version')::numeric >
            9223372036854775807::numeric
       or (expected_row.expected_value ->> 'active_step_index')::numeric >
            2147483647::numeric
  ) then
    raise exception
      '繳費單預期資料版本超出允許範圍，請重新載入後再處理'
      using errcode = '40001';
  end if;

  if v_action in ('return', 'reject', 'add_sign') and v_comment = '' then
    raise exception '退回、不通過或加簽必須填寫原因'
      using errcode = '22023';
  end if;
  if v_action = 'add_sign'
     and coalesce(p_add_sign_finance_user_id, '') = '' then
    raise exception '加簽必須指定人員'
      using errcode = '22023';
  end if;

  v_tenant_id := public.current_tenant_id();
  select finance_user.*
    into v_actor
  from public.finance_users finance_user
  where finance_user.tenant_id = v_tenant_id
    and finance_user.auth_user_id = auth.uid()
    and finance_user.active is true
  order by finance_user.created_at, finance_user.id
  limit 1;

  if not found then
    raise exception '目前登入帳號沒有此租戶的有效財務人員身分'
      using errcode = '42501';
  end if;  v_digest := private.finance_income_request_digest(
    pg_catalog.jsonb_build_object(
      'operation', 'bill_action',
      'environment', v_environment,
      'bill_ids', pg_catalog.to_jsonb(p_bill_ids),
      'action', v_action,
      'comment', v_comment,
      'files', coalesce(p_files, '[]'::jsonb),
      'add_sign_finance_user_id', p_add_sign_finance_user_id,
      'expected_steps', coalesce(p_expected_steps, '{}'::jsonb)
    )
  );
  v_cached := private.finance_income_begin_operation(
    v_tenant_id,
    v_environment,
    'bill_action',
    p_idempotency_key,
    v_digest,
    v_actor.id
  );
  if v_cached is not null then
    return v_cached || pg_catalog.jsonb_build_object(
      'idempotent_replay',
      true
    );
  end if;


  -- APPROVAL_V2_BILL_MEMBERSHIP_TABLE_LOCK
  -- CONCURRENCY WARNING: this deliberately serializes bill v2 mutations
  -- across all tenants. Contention fails within lock_timeout=5s for retry.
  lock table public.bills in share row exclusive mode;


  if v_action = 'add_sign' then
    select finance_user.*
      into v_target
    from public.finance_users finance_user
    where finance_user.tenant_id = v_tenant_id
      and finance_user.id = p_add_sign_finance_user_id
      and finance_user.active is true
    limit 1;

    if not found then
      raise exception '指定的加簽人不存在、已停用或不屬於目前租戶'
        using errcode = '23503';
    end if;
    if v_target.id = v_actor.id then
      raise exception '不可加簽自己'
        using errcode = '22023';
    end if;
  end if;


  -- BILL_BATCH_COMPLETE_SIBLINGS_GUARD_V1
  -- BILL_BATCH_SELECTED_IDS_SCOPE_GUARD_V1
  if (
    select pg_catalog.count(*)
    from public.bills selected_row
    where selected_row.tenant_id = v_tenant_id
      and selected_row.data_environment = v_environment
      and selected_row.id = any(p_bill_ids)
  ) <> pg_catalog.cardinality(p_bill_ids) then
    raise exception
      '部分繳費單不存在或不屬於目前租戶，請重新整理後再試'
      using errcode = '55000';
  end if;

  if exists (
    with selected_bill_rows as (
      select bill_row.id,
             nullif(pg_catalog.btrim(bill_row.batch_id), '') as batch_id
      from public.bills bill_row
      where bill_row.tenant_id = v_tenant_id
        and bill_row.data_environment = v_environment
        and bill_row.id = any(p_bill_ids)
    ),
    selected_batches as (
      select selected_bill.batch_id,
             pg_catalog.count(*) as selected_count
      from selected_bill_rows selected_bill
      where selected_bill.batch_id is not null
      group by selected_bill.batch_id
    )
    select 1
    from selected_batches selected_batch
    where selected_batch.selected_count <> (
      select pg_catalog.count(*)
      from public.bills sibling_row
      where sibling_row.tenant_id = v_tenant_id
        and sibling_row.data_environment = v_environment
        and nullif(pg_catalog.btrim(sibling_row.batch_id), '') =
            selected_batch.batch_id
    )
  ) then
    raise exception '同一批繳費單必須完整簽核，請重新整理後再試'
      using errcode = '55000';
  end if;

  for v_bill_id in
    select bill_id
    from pg_catalog.unnest(p_bill_ids) bill_id
    order by bill_id
  loop
    select bill_row.*
      into v_bill
    from public.bills bill_row
    where bill_row.tenant_id = v_tenant_id
      and bill_row.data_environment = v_environment
      and bill_row.id = v_bill_id
    for update;

    if not found then
      raise exception '繳費單不存在或不屬於目前租戶：%', v_bill_id
        using errcode = 'P0002';
    end if;
    -- APPROVAL_V2_LOCKED_ROW_VERSION_CAS
    v_expected_step := p_expected_steps -> v_bill_id;
    if v_bill.row_version is distinct from
         (v_expected_step ->> 'row_version')::bigint
       or coalesce(
            (v_expected_step ->> 'active_step_index')::int,
            -1
          ) <> private.finance_income_active_step_index(v_bill.steps)
       or coalesce(v_expected_step ->> 'role_key', '') <>
          coalesce(
            private.finance_income_step_role(
              v_bill.steps ->
              private.finance_income_active_step_index(v_bill.steps)
            ),
            ''
          )
       or coalesce(v_expected_step ->> 'finance_user_id', '') <>
          coalesce(
            private.finance_income_step_user_id(
              v_bill.steps ->
              private.finance_income_active_step_index(v_bill.steps)
            ),
            ''
          )
       or pg_catalog.lower(
            coalesce(v_expected_step ->> 'email', '')
          ) <> pg_catalog.lower(
            coalesce(
              v_bill.steps ->
                private.finance_income_active_step_index(v_bill.steps)
                ->> 'email',
              ''
            )
          )
       or coalesce(v_expected_step ->> 'approval_status', '') <>
          coalesce(v_bill.approval_status, '') then
      raise exception
        '繳費單內容或簽核關卡已被其他操作更新，請重新載入後再處理：%',
        v_bill_id
        using errcode = '40001';
    end if;

    if v_bill.voided_at is not null
       or v_bill.status in ('paid', 'void')
       or v_bill.approval_status in ('completed', 'rejected', 'cancelled') then
      raise exception '繳費單已結案，不能再執行簽核：%', v_bill_id
        using errcode = '55000';
    end if;

    v_steps := v_bill.steps;
    v_active_index := private.finance_income_active_step_index(v_steps);
    if v_active_index is null then
      raise exception '繳費單沒有待處理的簽核步驟：%', v_bill_id
        using errcode = '55000';
    end if;
    v_step := v_steps -> v_active_index;
    v_role_key := private.finance_income_step_role(v_step);

    if not private.finance_bill_actor_can_act(
      v_tenant_id,
      v_bill,
      v_active_index,
      v_step,
      v_actor.id,
      v_actor.email,
      v_actor.role
    ) then
      raise exception '您不是繳費單目前待簽步驟的有效處理人：%', v_bill_id
        using errcode = '42501';
    end if;

    if v_action in ('approve', 'add_sign') then
      v_step_updated := private.finance_income_append_step_action(
        v_step,
        v_actor.id,
        v_actor.name,
        case
          when v_action = 'add_sign' then '簽核通過並加簽'
          else '簽核通過'
        end,
        v_comment,
        p_files
      ) || pg_catalog.jsonb_build_object('a', 'approved');
      v_steps := pg_catalog.jsonb_set(
        v_steps,
        array[v_active_index::text],
        v_step_updated,
        false
      );

      if v_action = 'add_sign' then
        v_add_step := pg_catalog.jsonb_build_object(
          'r', '加簽：' || v_target.name,
          'rk', 'assigned_user',
          'uid', v_target.id,
          'n', '',
          'a', '',
          't', '',
          'c', '加簽原因：' || v_comment,
          'files', '[]'::jsonb,
          'status', 'pending_countersign',
          'requestedBy', v_actor.name
        );
        v_steps := pg_catalog.jsonb_insert(
          v_steps,
          array[v_active_index::text],
          v_add_step,
          true
        );
      end if;
    elsif v_action = 'reject' then
      v_step_updated := private.finance_income_append_step_action(
        v_step,
        v_actor.id,
        v_actor.name,
        '不通過',
        v_comment,
        p_files
      ) || pg_catalog.jsonb_build_object('a', 'rejected');
      v_steps := pg_catalog.jsonb_set(
        v_steps,
        array[v_active_index::text],
        v_step_updated,
        false
      );
    else
      v_previous_index := v_active_index - 1;
      while v_previous_index >= 0 loop
        v_previous_step := v_steps -> v_previous_index;
        exit when pg_catalog.lower(
          coalesce(v_previous_step ->> 'autoSkip', 'false')
        ) <> 'true';
        v_previous_index := v_previous_index - 1;
      end loop;

      if v_previous_index < 0 then
        raise exception '繳費單目前沒有可退回的上一關：%', v_bill_id
          using errcode = '55000';
      end if;

      v_step_updated := private.finance_income_append_step_action(
        v_step,
        v_actor.id,
        v_actor.name,
        '退回上一關',
        v_comment,
        p_files
      );
      v_steps := pg_catalog.jsonb_set(
        v_steps,
        array[v_active_index::text],
        v_step_updated,
        false
      );
      v_previous_step := v_steps -> v_previous_index;

      if private.finance_income_step_role(v_previous_step) =
         'applicant_submit' then
        v_revision_step := pg_catalog.jsonb_build_object(
          'r', '申請人補件後重新送出',
          'rk', 'applicant_revision',
          'uid', v_bill.applicant_id,
          'n', '',
          'a', '',
          't', '',
          'c', '',
          'files', '[]'::jsonb,
          'status', 'pending_applicant_confirm'
        );
        v_revision_step := private.finance_income_append_step_action(
          v_revision_step,
          v_actor.id,
          v_actor.name,
          '退回上一關',
          v_comment,
          p_files
        ) - 'n' - 't';
        v_steps := pg_catalog.jsonb_insert(
          v_steps,
          array[v_active_index::text],
          v_revision_step,
          false
        );
      else
        v_previous_step := private.finance_income_append_step_action(
          v_previous_step - 'a' - 'n' - 't',
          v_actor.id,
          v_actor.name,
          '退回上一關',
          v_comment,
          p_files
        ) - 'a' - 'n' - 't';
        v_steps := pg_catalog.jsonb_set(
          v_steps,
          array[v_previous_index::text],
          v_previous_step,
          false
        );
      end if;
    end if;

    if v_action = 'reject' then
      v_status := pg_catalog.jsonb_build_object(
        'approval_status', 'rejected',
        'approval_step', v_active_index + 1
      );
    else
      v_status := private.finance_income_status_from_steps(v_steps);
    end if;

    update public.bills bill_row
       set steps = v_steps,
           approval_status = v_status ->> 'approval_status',
           approval_step = (v_status ->> 'approval_step')::int
     where bill_row.tenant_id = v_tenant_id
       and bill_row.data_environment = v_environment
       and bill_row.id = v_bill_id;

    v_result_rows := v_result_rows || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'id', v_bill_id,
        'no', v_bill.no,
        'action', v_action,
        'active_role_key', v_role_key,
        'approval_status', v_status ->> 'approval_status',
        'approval_step', (v_status ->> 'approval_step')::int
      )
    );
  end loop;

  v_result := pg_catalog.jsonb_build_object(
    'ok', true,
    'idempotent_replay', false,
    'document_type', 'bill',
    'action', v_action,
    'idempotency_key', p_idempotency_key,
    'count', pg_catalog.jsonb_array_length(v_result_rows),
    'rows', v_result_rows
  );
  perform private.finance_income_finish_operation(
    v_tenant_id,
    v_environment,
    'bill_action',
    p_idempotency_key,
    v_result
  );
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_income_withdraw_applicant_v1(p_document_type text, p_document_ids text[], p_idempotency_key text, p_comment text, p_expected_steps jsonb, p_data_environment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET lock_timeout TO '5s'
AS $function$
declare
  v_kind text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_document_type, '')));
  v_environment text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_data_environment, 'production')));
  v_comment text := pg_catalog.btrim(coalesce(p_comment, ''));
  v_tenant_id uuid;
  v_actor public.finance_users%rowtype;
  v_operation_type text;
  v_max_items integer;
  v_digest text;
  v_cached jsonb;
  v_id text;
  v_document jsonb;
  v_expected jsonb;
  v_steps jsonb;
  v_step jsonb;
  v_active_index integer;
  v_step_role text;
  v_step_updated jsonb;
  v_result_rows jsonb := '[]'::jsonb;
  v_result jsonb;
  v_next_version bigint;
begin
  if auth.uid() is null then
    raise exception '請先登入後再抽單' using errcode = '42501';
  end if;
  if v_kind not in ('bill', 'invoice') then
    raise exception '只能抽回繳費單或發票申請' using errcode = '22023';
  end if;
  if v_environment not in ('production', 'test') then
    raise exception '資料環境只允許 production 或 test' using errcode = '22023';
  end if;
  if v_comment = '' or pg_catalog.char_length(v_comment) > 2000 then
    raise exception '請填寫 1 到 2000 字的抽單原因' using errcode = '22023';
  end if;
  if v_kind = 'bill' then
    v_max_items := 150;
  else
    v_max_items := 500;
  end if;
  if p_document_ids is null
     or pg_catalog.cardinality(p_document_ids) < 1
     or pg_catalog.cardinality(p_document_ids) > v_max_items
     or exists (
       select 1 from pg_catalog.unnest(p_document_ids) item(id)
       where pg_catalog.btrim(coalesce(item.id, '')) = ''
     )
     or pg_catalog.cardinality(p_document_ids) <> (
       select pg_catalog.count(distinct item.id)
       from pg_catalog.unnest(p_document_ids) item(id)
     ) then
    raise exception '抽單筆數或單據識別碼錯誤' using errcode = '22023';
  end if;
  if pg_catalog.jsonb_typeof(p_expected_steps) <> 'object'
     or (select pg_catalog.count(*)
         from pg_catalog.jsonb_object_keys(p_expected_steps)) <>
        pg_catalog.cardinality(p_document_ids)
     or exists (
       select 1
       from pg_catalog.jsonb_object_keys(p_expected_steps) expected_id(id)
       where not (expected_id.id = any(p_document_ids))
     )
     or exists (
       select 1
       from pg_catalog.jsonb_each(p_expected_steps) expected_row(id, value)
       where pg_catalog.jsonb_typeof(expected_row.value) <> 'object'
          or pg_catalog.jsonb_typeof(expected_row.value -> 'row_version') <> 'number'
          or pg_catalog.jsonb_typeof(expected_row.value -> 'active_step_index') <> 'number'
          or coalesce(expected_row.value ->> 'row_version', '') !~ '^[1-9][0-9]{0,18}$'
          or coalesce(expected_row.value ->> 'active_step_index', '') !~ '^(0|[1-9][0-9]{0,9})$'
     ) then
    raise exception '抽單預期資料版本不完整，請重新載入後再處理'
      using errcode = '40001';
  end if;
  if exists (
    select 1
    from pg_catalog.jsonb_each(p_expected_steps) expected_row(id, value)
    where (expected_row.value ->> 'row_version')::numeric >
            9223372036854775807::numeric
       or (expected_row.value ->> 'active_step_index')::numeric >
            2147483647::numeric
  ) then
    raise exception '抽單預期資料版本超出允許範圍，請重新載入後再處理'
      using errcode = '40001';
  end if;

  v_tenant_id := public.current_tenant_id();
  select finance_user.* into v_actor
  from public.finance_users finance_user
  where finance_user.tenant_id = v_tenant_id
    and finance_user.auth_user_id = auth.uid()
    and finance_user.active is true
  order by finance_user.created_at, finance_user.id
  limit 1;
  if not found then
    raise exception '目前登入帳號沒有此租戶的有效財務人員身分'
      using errcode = '42501';
  end if;

  v_operation_type := v_kind || '_action';
  v_digest := private.finance_income_request_digest(
    pg_catalog.jsonb_build_object(
      'operation', v_operation_type,
      'environment', v_environment,
      'document_ids', pg_catalog.to_jsonb(p_document_ids),
      'action', 'withdraw',
      'comment', v_comment,
      'expected_steps', p_expected_steps
    )
  );
  v_cached := private.finance_income_begin_operation(
    v_tenant_id, v_environment, v_operation_type,
    p_idempotency_key, v_digest, v_actor.id
  );
  if v_cached is not null then
    return v_cached || pg_catalog.jsonb_build_object('idempotent_replay', true);
  end if;

  if v_kind = 'bill' then
    -- Same complete-sibling guarantee as the current bill approval RPC.
    lock table public.bills in share row exclusive mode;
    if (
      select pg_catalog.count(*) from public.bills bill_row
      where bill_row.tenant_id = v_tenant_id
        and bill_row.data_environment = v_environment
        and bill_row.id = any(p_document_ids)
    ) <> pg_catalog.cardinality(p_document_ids) then
      raise exception '部分繳費單不存在或不屬於目前租戶，請重新整理後再試'
        using errcode = '55000';
    end if;
    if exists (
      with selected as (
        select nullif(pg_catalog.btrim(bill_row.batch_id), '') as batch_id,
               pg_catalog.count(*) as selected_count
        from public.bills bill_row
        where bill_row.tenant_id = v_tenant_id
          and bill_row.data_environment = v_environment
          and bill_row.id = any(p_document_ids)
          and nullif(pg_catalog.btrim(bill_row.batch_id), '') is not null
        group by nullif(pg_catalog.btrim(bill_row.batch_id), '')
      )
      select 1 from selected s
      where s.selected_count <> (
        select pg_catalog.count(*) from public.bills sibling
        where sibling.tenant_id = v_tenant_id
          and sibling.data_environment = v_environment
          and nullif(pg_catalog.btrim(sibling.batch_id), '') = s.batch_id
      )
    ) then
      raise exception '同一批繳費單必須完整抽單，請重新整理後再試'
        using errcode = '55000';
    end if;
  else
    lock table public.invoices in share row exclusive mode;
    if (
      select pg_catalog.count(*) from public.invoices invoice_row
      where invoice_row.tenant_id = v_tenant_id
        and invoice_row.data_environment = v_environment
        and invoice_row.id = any(p_document_ids)
    ) <> pg_catalog.cardinality(p_document_ids) then
      raise exception '部分發票申請不存在或不屬於目前租戶，請重新整理後再試'
        using errcode = '55000';
    end if;
    if exists (
      with selected as (
        select nullif(pg_catalog.btrim(invoice_row.batch_id), '') as batch_id,
               pg_catalog.count(*) as selected_count
        from public.invoices invoice_row
        where invoice_row.tenant_id = v_tenant_id
          and invoice_row.data_environment = v_environment
          and invoice_row.id = any(p_document_ids)
          and nullif(pg_catalog.btrim(invoice_row.batch_id), '') is not null
        group by nullif(pg_catalog.btrim(invoice_row.batch_id), '')
      )
      select 1 from selected s
      where s.selected_count <> (
        select pg_catalog.count(*) from public.invoices sibling
        where sibling.tenant_id = v_tenant_id
          and sibling.data_environment = v_environment
          and nullif(pg_catalog.btrim(sibling.batch_id), '') = s.batch_id
      )
    ) then
      raise exception '同一批發票申請必須完整抽單，請重新整理後再試'
        using errcode = '55000';
    end if;
  end if;

  for v_id in
    select item.id from pg_catalog.unnest(p_document_ids) item(id)
    order by item.id
  loop
    if v_kind = 'bill' then
      select pg_catalog.to_jsonb(bill_row) into v_document
      from public.bills bill_row
      where bill_row.tenant_id = v_tenant_id
        and bill_row.data_environment = v_environment
        and bill_row.id = v_id
      for update;
    else
      select pg_catalog.to_jsonb(invoice_row) into v_document
      from public.invoices invoice_row
      where invoice_row.tenant_id = v_tenant_id
        and invoice_row.data_environment = v_environment
        and invoice_row.id = v_id
      for update;
    end if;
    if v_document is null then
      raise exception '單據不存在或不屬於目前租戶：%', v_id
        using errcode = 'P0002';
    end if;
    if coalesce(v_document ->> 'applicant_id', '') <> v_actor.id then
      raise exception '只有原申請人可以抽單：%', v_id
        using errcode = '42501';
    end if;
    v_expected := p_expected_steps -> v_id;
    v_steps := coalesce(v_document -> 'steps', '[]'::jsonb);
    if pg_catalog.jsonb_typeof(v_steps) <> 'array' then
      raise exception '單據簽核步驟格式錯誤：%', v_id
        using errcode = '22023';
    end if;
    v_active_index := private.finance_income_active_step_index(v_steps);
    if v_active_index is null
       or coalesce(v_document ->> 'approval_status', '') not like 'pending%'
       or coalesce(v_document ->> 'approval_step', '') <> (v_active_index + 1)::text then
      raise exception '單據已結案或沒有待處理關卡，不能抽單：%', v_id
        using errcode = '55000';
    end if;
    v_step := v_steps -> v_active_index;
    v_step_role := private.finance_income_step_role(v_step);
    if (v_document ->> 'row_version')::bigint is distinct from
         (v_expected ->> 'row_version')::bigint
       or v_active_index is distinct from
         (v_expected ->> 'active_step_index')::integer
       or coalesce(v_step_role, '') <>
          coalesce(v_expected ->> 'role_key', '')
       or coalesce(private.finance_income_step_user_id(v_step), '') <>
          coalesce(v_expected ->> 'finance_user_id', '')
       or pg_catalog.lower(coalesce(v_step ->> 'email', '')) <>
          pg_catalog.lower(coalesce(v_expected ->> 'email', ''))
       or coalesce(v_document ->> 'approval_status', '') <>
          coalesce(v_expected ->> 'approval_status', '') then
      raise exception '單據內容或關卡已更新，請重新載入後再抽單：%', v_id
        using errcode = '40001';
    end if;

    if v_kind = 'bill' then
      if coalesce(v_document ->> 'status', '') <> 'unpaid'
         or nullif(v_document ->> 'paid_at', '') is not null
         or nullif(v_document ->> 'voided_at', '') is not null
         or nullif(v_document ->> 'linked_invoice_id', '') is not null
         or coalesce(v_document ->> 'invoice_followup_status', 'unreviewed') <> 'unreviewed'
         or exists (
           select 1 from public.invoices invoice_row
           where invoice_row.tenant_id = v_tenant_id
             and invoice_row.data_environment = v_environment
             and invoice_row.source_bill_id = v_id
         ) then
        raise exception '繳費單已收款、連結發票或進入後續處理，不能直接抽單：%', v_id
          using errcode = '55000';
      end if;
    else
      -- accountant_invoice approval is the issue step. A document waiting for
      -- applicant delivery has already been issued even if posting flags have
      -- not yet caught up; it needs an invoice void/credit workflow instead.
      if coalesce(v_document ->> 'approval_status', '') = 'pending_invoice_delivery'
         or exists (
           select 1
           from pg_catalog.jsonb_array_elements(v_steps) issue_step
           where private.finance_income_step_role(issue_step) in (
             'accountant_invoice', 'invoice_issue', 'invoice_issuance'
           )
             and pg_catalog.lower(coalesce(issue_step ->> 'a', '')) in (
               'approved', 'auto'
             )
         )
         or coalesce(v_document ->> 'status', '') <> 'unpaid'
         or nullif(v_document ->> 'paid_at', '') is not null
         or nullif(v_document ->> 'voided_at', '') is not null
         or nullif(v_document ->> 'posting_locked_at', '') is not null
         or nullif(v_document ->> 'revenue_posted_at', '') is not null
         or coalesce((v_document ->> 'revenue_posted')::boolean, false)
         -- `deferred` means the revenue posting was postponed, not completed.
         -- Actual posting markers and lifecycle events above/below still block.
         or coalesce(v_document ->> 'revenue_posting_state', 'not_posted')
              not in ('not_posted', 'deferred')
         or nullif(v_document ->> 'cash_receipt_posted_at', '') is not null
         or nullif(v_document ->> 'receipt_submitted_at', '') is not null
         or nullif(v_document ->> 'receipt_reviewed_at', '') is not null
         or coalesce(v_document -> 'receipt_files', '[]'::jsonb) <> '[]'::jsonb
         or nullif(v_document ->> 'source_bill_id', '') is not null
         or exists (
           select 1 from public.invoice_lifecycle_events event_row
           where event_row.tenant_id = v_tenant_id
             and event_row.data_environment = v_environment
             and event_row.invoice_id = v_id
         ) then
        raise exception '發票已開立、收款、入帳或連結其他單據，不能直接抽單：%', v_id
          using errcode = '55000';
      end if;
    end if;

    v_step_updated := private.finance_income_append_step_action(
      v_step, v_actor.id, v_actor.name,
      '申請人自行抽單', v_comment, '[]'::jsonb
    ) || pg_catalog.jsonb_build_object(
      'a', 'cancelled',
      'cancelledAt', pg_catalog.now(),
      'cancelledById', v_actor.id,
      'cancelReason', v_comment
    );
    v_steps := pg_catalog.jsonb_set(
      v_steps, array[v_active_index::text], v_step_updated, false
    );

    if v_kind = 'bill' then
      update public.bills bill_row
      set steps = v_steps,
          status = 'cancelled',
          approval_status = 'cancelled',
          approval_step = v_active_index + 1
      where bill_row.tenant_id = v_tenant_id
        and bill_row.data_environment = v_environment
        and bill_row.id = v_id
        and bill_row.row_version = (v_document ->> 'row_version')::bigint
      returning bill_row.row_version into v_next_version;
    else
      update public.invoices invoice_row
      set steps = v_steps,
          status = 'cancelled',
          approval_status = 'cancelled',
          approval_step = v_active_index + 1,
          updated_at = pg_catalog.now()
      where invoice_row.tenant_id = v_tenant_id
        and invoice_row.data_environment = v_environment
        and invoice_row.id = v_id
        and invoice_row.row_version = (v_document ->> 'row_version')::bigint
      returning invoice_row.row_version into v_next_version;
    end if;
    if not found then
      raise exception '抽單時資料版本已變更，整批未寫入：%', v_id
        using errcode = '40001';
    end if;
    -- Existing synchronization triggers log warnings and swallow exceptions.
    -- Run the three financial projections directly so a failed projection
    -- rolls back the source cancellation and every sibling in this batch.
    if v_kind = 'bill' then
      perform private.upsert_bill_collection_followup(v_id);
      perform private.upsert_bill_income_closure(v_id);
      perform private.upsert_cash_evidence_for_bill(v_id);
    else
      perform private.upsert_invoice_collection_followup(v_id);
      perform private.upsert_invoice_income_closure(v_id);
      perform private.upsert_cash_evidence_for_invoice(v_id);
    end if;
    if not exists (
      select 1 from public.collection_followups followup_row
      where followup_row.tenant_id = v_tenant_id
        and followup_row.data_environment = v_environment
        and followup_row.source_table = v_kind || 's'
        and followup_row.source_id = v_id
        and followup_row.outstanding_amount = 0
        and followup_row.payment_status = 'voided'
        and followup_row.followup_status = 'void'
    ) or not exists (
      select 1 from public.income_document_closure_cases closure_row
      where closure_row.tenant_id = v_tenant_id
        and closure_row.data_environment = v_environment
        and closure_row.source_table = v_kind || 's'
        and closure_row.source_id = v_id
        and closure_row.closure_status = 'closed_void'
    ) or not exists (
      select 1 from public.cash_movement_evidence_links cash_row
      where cash_row.tenant_id = v_tenant_id
        and cash_row.data_environment = v_environment
        and cash_row.source_table = v_kind || 's'
        and cash_row.source_id = v_id
        and cash_row.cash_stage = 'void'
    ) then
      raise exception '抽單後應收、現金或結案資料未同步，整批已回復：%', v_id
        using errcode = '55000';
    end if;
    v_result_rows := v_result_rows || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'id', v_id,
        'no', v_document ->> 'no',
        'action', 'withdraw',
        'status', 'cancelled',
        'approval_status', 'cancelled',
        'approval_step', v_active_index + 1,
        'row_version', v_next_version
      )
    );
  end loop;

  v_result := pg_catalog.jsonb_build_object(
    'ok', true,
    'idempotent_replay', false,
    'document_type', v_kind,
    'action', 'withdraw',
    'idempotency_key', p_idempotency_key,
    'count', pg_catalog.jsonb_array_length(v_result_rows),
    'rows', v_result_rows
  );
  perform private.finance_income_finish_operation(
    v_tenant_id, v_environment, v_operation_type,
    p_idempotency_key, v_result
  );
  return v_result;
end;
$function$
